/**
 * Project description and content parsing utility.
 * Handles both rich-text HTML (generated by the admin editor)
 * and legacy delimiter-separated plain text (•, -, \n).
 */

export interface ProjectContentParts {
  /** Clean summary / executive overview text (paragraphs separated by newline) */
  overview: string;
  /** Individual scope / systems bullet items */
  scopeBullets: string[];
  /** Whether the original source was formatted HTML */
  isHtml: boolean;
}

/**
 * Decodes common HTML entities into their plain text equivalents.
 */
export function decodeHtmlEntities(str: string): string {
  if (!str) return "";
  return str
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/&nbsp;/g, " ")
    .replace(/&#x2F;/g, "/")
    .replace(/&#(\d+);/g, (_, dec) => String.fromCharCode(Number(dec)));
}

/**
 * Strips HTML tags and collapses whitespace, returning clean plain text.
 */
export function stripHtmlTags(html: string): string {
  if (!html) return "";
  const withoutTags = html.replace(/<[^>]*>?/gm, " ");
  return decodeHtmlEntities(withoutTags).replace(/\s+/g, " ").trim();
}

const SECTION_HEADERS_EN = [
  "project overview",
  "scope of work",
  "scope of works",
  "systems integrated",
  "key systems",
  "overview",
];

const SECTION_HEADERS_AR = [
  "نبذة عن المشروع",
  "نطاق الأعمال",
  "نطاق العمل",
  "الأنظمة المنفذة",
  "نظرة عامة",
];

const CATEGORY_HEADING_REGEX = /^(security & access control|it infrastructure & cybersecurity|audiovisual & communication|smart building & automation|parking & centralized operations|الأنظمة الأمنية والتحكم في الدخول|البنية التحتية لتكنولوجيا المعلومات والأمن السيبراني|الأنظمة السمعية والبصرية والاتصالات|المباني الذكية والأتمتة|إدارة المواقف والتشغيل المركزي)/i;

/**
 * Parses and formats project description content into structured parts:
 * an executive overview paragraph and individual scope highlight bullets.
 */
export function formatProjectContent(rawDesc: string | undefined | null): ProjectContentParts {
  if (!rawDesc || typeof rawDesc !== "string") {
    return { overview: "", scopeBullets: [], isHtml: false };
  }

  const trimmed = rawDesc.trim();
  const isHtml = /<[a-z][\s\S]*>/i.test(trimmed);

  if (isHtml) {
    // 1. Extract <li> items for discrete scope systems
    const liMatches = [...trimmed.matchAll(/<li[^>]*>([\s\S]*?)<\/li>/gi)];
    const scopeBullets = liMatches
      .map((m) => stripHtmlTags(m[1]))
      .filter((text) => Boolean(text && text.length > 1));

    // 2. Extract overview paragraphs by stripping out list containers (<ul>, <ol>)
    const withoutLists = trimmed
      .replace(/<ul[^>]*>[\s\S]*?<\/ul>/gi, " ")
      .replace(/<ol[^>]*>[\s\S]*?<\/ol>/gi, " ");

    const pMatches = [...withoutLists.matchAll(/<p[^>]*>([\s\S]*?)<\/p>/gi)];

    const allHeaders = [...SECTION_HEADERS_EN, ...SECTION_HEADERS_AR];

    const paragraphs = pMatches
      .map((m) => stripHtmlTags(m[1]))
      .filter((t) => {
        if (!t) return false;
        const lower = t.toLowerCase();
        // Ignore static section heading titles
        if (allHeaders.some((h) => lower === h || lower.startsWith(h + ":"))) return false;
        // Ignore sub-category grouping headings (like "Security & Access Control")
        if (CATEGORY_HEADING_REGEX.test(t)) return false;
        return true;
      });

    const overview = paragraphs.join("\n\n");

    return {
      overview,
      scopeBullets,
      isHtml: true,
    };
  }

  // Plain text fallback (delimiter-separated bullets)
  const clean = decodeHtmlEntities(trimmed);
  let scopeBullets: string[] = [];
  let overview = "";

  if (clean.includes("•")) {
    scopeBullets = clean.split("•").map((s) => s.trim()).filter(Boolean);
  } else if (clean.includes(" - ")) {
    scopeBullets = clean.split(" - ").map((s) => s.trim()).filter(Boolean);
  } else if (clean.includes("\n")) {
    scopeBullets = clean.split("\n").map((s) => s.trim()).filter(Boolean);
  } else {
    overview = clean;
  }

  return {
    overview,
    scopeBullets,
    isHtml: false,
  };
}

